def determinize(A: FiniteStateAutomaton, log=False) -> FiniteStateAutomaton:
  Iʹ = fset({A.I})
  Qʹ, δʹ, V = set(Iʹ), {}, set()
  if log:
    print(Iʹ, Qʹ, δʹ, V)
  while Qʹ != V:
    qʹ = (Qʹ - V).pop()
    V |= {qʹ}
    for a in A.Σ:
      rʹ = δ̂(A.δ, qʹ, a)
      if rʹ != set():
        Qʹ |= {rʹ}
        δʹ = merge(δʹ, {qʹ: {a: {rʹ}}})
    if log:
      print(Qʹ, δʹ, V)
  Fʹ = {qʹ for qʹ in Qʹ if qʹ & A.F != set()}
  return FiniteStateAutomaton(A.Σ, Qʹ, Iʹ, δʹ, Fʹ)
```

```python
def equiv(A: FiniteStateAutomaton, B: FiniteStateAutomaton, log=False) -> bool:
  W, V = {(A.I, B.I)}, set()  # work, visited
  while W != set():
    P, Q = W.pop()
    if (P, Q) not in V:
      if log:
        print('checking', P, Q)
      if (P & A.F == set()) != (Q & B.F == set()):
        return False
      for a in A.Σ | B.Σ:
        W |= {(δ̂(A.δ, P, a), δ̂(B.δ, Q, a))}
      V |= {(P, Q)}
  if log:
    print('equivalent', V)
  return True
```

